        ),
        "endsinpunc": (
            False if bool(re.match(r".+[^.\w]", token, flags=re.UNICODE)) else token[-1]
        ),
        "directional": token_abbrev not in DIRECTIONS,
        "street_name": token_abbrev not in STREET_NAMES,
        "has.vowels": bool(set(token_abbrev) & set("aeiou")),
    }

    return features
EOF
